- * calibration and OTP programming is irreversible.
+ * Read behavior follows the control flow of the BK7258 Armino authority
+ * middleware/driver/otp/otp_driver_v1_1.c.  The NuttX integration replaces
+ * the Armino OTP HAL with the equivalent BK7258 MMIO transactions, and uses a
+ * NuttX spinlock for the OTP_ACTIVE()/OTP_SLEEP() critical region.
+ *
+ * Programming remains refused: no runtime Wi-Fi path needs it and OTP
+ * programming is irreversible.
@@
 static spinlock_t g_otp_lock = SP_UNLOCKED;
+static const struct bk7258_otp_item_s *g_otp_map;
+static size_t g_otp_map_items;
+
+/* These are the NuttX-integrated equivalents of the authority's
+ * switch_map(), otp_active(), and otp_sleep() helpers.  Keeping that ordering
+ * matters: the authority performs a permission/mask read in one active
+ * window, closes it, then opens a fresh window for the data read. */
+
+static int bk7258_otp_switch_map(unsigned int map_id)
+{
+  if (g_otp_map != NULL)
+    {
+      return -EBUSY;
+    }
+
+  if (map_id == 1)
+    {
+      g_otp_map = g_bk7258_otp1_map;
+      g_otp_map_items = BK7258_OTP1_ITEMS;
+      return OK;
+    }
+
+  if (map_id == 2)
+    {
+      g_otp_map = g_bk7258_otp2_map;
+      g_otp_map_items = BK7258_OTP2_ITEMS;
+      return OK;
+    }
+
+  return -EINVAL;
+}
@@
 static void bk7258_otp_sleep(void)
 {
@@
   modifyreg32(BK7258_SYS_DEV_CLK_EN, BK7258_SYS_OTP_CLK_EN, 0);
 }
+
+static int bk7258_otp_active_map(unsigned int map_id)
+{
+  int ret = bk7258_otp_switch_map(map_id);
+
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  ret = bk7258_otp_activate();
+  if (ret < 0)
+    {
+      bk7258_otp_sleep();
+      g_otp_map = NULL;
+      g_otp_map_items = 0;
+    }
+
+  return ret;
+}
+
+static void bk7258_otp_sleep_map(void)
+{
+  bk7258_otp_sleep();
+  g_otp_map = NULL;
+  g_otp_map_items = 0;
+}
@@
