+static bk_err_t bk7258_otp_read(unsigned int map_id, uint8_t *buf,
+                                 uint32_t size)
+{
+  uintptr_t base;
+  const struct bk7258_otp_item_s *entry;
+  uint32_t word;
+  uint32_t start;
+  uint32_t value;
