-      spin_unlock_irqrestore(&g_otp_lock, flags);
-      return BK_ERR_NO_READ_PERMISSION;
+      return BK_ERR_OTP_READ_BUFFER_NULL;
     }

-  start = entry->offset % 4;
+  flags = spin_lock_irqsave(&g_otp_lock);
+  ret = bk7258_otp_active_map(map_id);
+  if (ret < 0)
+    {
+      spin_unlock_irqrestore(&g_otp_lock, flags);
+      return BK_FAIL;
+    }
+
+  entry = g_otp_map;
+  if (size > entry->size)
+    {
+      bk7258_otp_sleep_map();
+      spin_unlock_irqrestore(&g_otp_lock, flags);
+      return BK_ERR_OTP_ADDR_OUT_OF_RANGE;
+    }
+
+  word = entry->offset / 4;
+  permission = map_id == 2 ? bk7258_otp2_permission(word) :
+                             bk7258_otp1_permission(word);
