+  ret = bk7258_otp_active_map(map_id);
+  if (ret < 0)
+    {
+      spin_unlock_irqrestore(&g_otp_lock, flags);
+      return BK_FAIL;
+    }
+
+  entry = g_otp_map;
+  /* Match Armino's public read: validate the requested item against the map
+   * in the first active window, then reopen OTP for the actual word reads. */
+  base = map_id == 2 ? BK7258_OTP_AHB_BASE : OTP1_DATA;
+  word = entry->offset / 4;
+  start = entry->offset % 4;
   while (size > 0)
     {
-      uint32_t value = getreg32(base + (word << 2));
+      value = getreg32(base + (word << 2));
       uint32_t count = size < 4 - start ? size : 4 - start;
       uint32_t index;
@@
       word++;
       start = 0;
     }

-  bk7258_otp_sleep();
+  bk7258_otp_sleep_map();
   spin_unlock_irqrestore(&g_otp_lock, flags);
   return BK_OK;
 }
@@
 bk_err_t bk_otp_apb_read(otp1_id_t item, uint8_t *buf, uint32_t size)
 {
@@
-  return bk7258_otp_read(&g_bk7258_otp1_map[item], false, buf, size);
+  /* This mirrors bk_otp_apb_read() in otp_driver_v1_1.c: validate the item
+   * before entering the authority-style permission/read sequence. */
+  return bk7258_otp_read(1, buf, size);
 }
@@
-  return bk7258_otp_read(&g_bk7258_otp2_map[item], true, buf, size);
+  /* Equivalent to the authority's bk_otp_ahb_read() read-only path. */
+  return bk7258_otp_read(2, buf, size);
 }
*** End Patch`;
const edit=await tools.apply_patch({patch_text:patch});
return {edit:edit.output};

