const source=`/****************************************************************************
 * chips/bk7258/mb_ipc/mb_ipc_rpmsg.c
 *
 * Armino mb_ipc API and state semantics transported by Vela RPMsg.
 *
 * The Armino mailbox implementation passes a shared-memory pointer in
 * mb_ipc_cmd_t::cmd_data_buff. That representation is not valid across the
 * CP/AP RPMsg endpoint boundary, so this transport carries the same logical
 * command (CPU/port/tag/user command/CRC/status) and payload bytes in framed
 * RPMsg messages. It preserves the authority socket lifecycle and does not
 * use the hardware PMOP doorbell as a generic RPC substitute.
 ****************************************************************************/

#include <nuttx/config.h>

#if defined(CONFIG_RPMSG) && defined(CONFIG_BK7258_MAILBOX)

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/rpmsg/rpmsg.h>
#include <nuttx/semaphore.h>

#include <openamp/rpmsg.h>

#include <common/bk_include.h>
#include <driver/mb_ipc.h>
#include <driver/mb_ipc_port_cfg.h>

#include <bk7258_mb_ipc.h>

#define BK7258_MBIPC_SERVICE_NAME       "bk7258.mb_ipc.v1"
#define BK7258_MBIPC_MAGIC              UINT32_C(0x4d424950) /* MBIP */
#define BK7258_MBIPC_VERSION            1
#define BK7258_MBIPC_FRAGMENT_BYTES     384
#define BK7258_MBIPC_MAX_PAYLOAD        1024
#define BK7258_MBIPC_SERVER_PORTS       4
#define BK7258_MBIPC_CLIENT_PORTS       12
#define BK7258_MBIPC_CONNECTIONS        3
#define BK7258_MBIPC_INVALID_CONNECT    UINT8_C(0xff)

#define BK7258_MBIPC_FRAME_REQUEST      UINT8_C(0)
#define BK7258_MBIPC_FRAME_ACK          UINT8_C(1)
#define BK7258_MBIPC_FRAME_CONNECT      UINT8_C(2)
#define BK7258_MBIPC_FRAME_DISCONNECT   UINT8_C(3)

#define BK7258_MBIPC_STATE_ALLOCATED    UINT8_C(0x01)
#define BK7258_MBIPC_STATE_CONNECTED    UINT8_C(0x02)
#define BK7258_MBIPC_STATE_TX           UINT8_C(0x04)
#define BK7258_MBIPC_STATE_RX           UINT8_C(0x08)

#define BK7258_MBIPC_SERVER_HANDLE      UINT32_C(0x80000000)
#define BK7258_MBIPC_CONNECT_HANDLE     UINT32_C(0x40000000)
#define BK7258_MBIPC_HANDLE_PORT_MASK   UINT32_C(0x0000003f)
#define BK7258_MBIPC_HANDLE_CONN_SHIFT  8
#define BK7258_MBIPC_HANDLE_CONN_MASK   UINT32_C(0x00000300)

begin_packed_struct struct bk7258_mbipc_frame_s
{
  uint32_t magic;
  uint8_t version;
  uint8_t kind;
  uint8_t command;
  uint8_t src_cpu;
  uint8_t dst_cpu;
  uint8_t src_port;
  uint8_t dst_port;
  uint8_t connect_id;
  uint8_t tag;
  uint8_t user_cmd;
  uint8_t route_status;
  uint8_t api_status;
  uint8_t crc8;
  uint16_t total_len;
  uint16_t fragment_offset;
  uint16_t fragment_len;
  uint8_t payload[0];
} end_packed_struct;

struct bk7258_mbipc_socket_s
{
  uint8_t state;
  uint8_t src_cpu;
  uint8_t src_port;
  uint8_t dst_cpu;
  uint8_t dst_port;
  uint8_t connect_id;
  uint8_t tx_tag;
  uint8_t tx_command;
  uint8_t tx_status;
  uint8_t rx_tag;
  uint8_t rx_command;
  uint8_t rx_user_cmd;
  uint16_t tx_len;
  uint16_t rx_total;
  uint16_t rx_next;
  mb_ipc_notify_isr_t callback;
  sem_t tx_sem;
  uint8_t buffer[BK7258_MBIPC_MAX_PAYLOAD];
};

struct bk7258_mbipc_server_s
{
  bool allocated;
  mb_ipc_notify_isr_t callback;
  struct bk7258_mbipc_socket_s connection[BK7258_MBIPC_CONNECTIONS];
};

struct bk7258_mbipc_transport_s
{
  nxmutex_t lock;
  struct rpmsg_endpoint ept;
  struct rpmsg_device *rdev;
  bool registered;
  bool online;
  struct bk7258_mbipc_server_s server[BK7258_MBIPC_SERVER_PORTS];
  struct bk7258_mbipc_socket_s client[BK7258_MBIPC_CLIENT_PORTS];
};

static struct bk7258_mbipc_transport_s g_mbipc =
{
  .lock = NXMUTEX_INITIALIZER,
};

static uint8_t bk7258_mbipc_local_cpu(void)
{
#ifdef CONFIG_BK7258_COMPONENT_CP
  return 0;
#else
  /* CPU1 and CPU2 are one AP SMP domain. Armino mb_ipc clients for PHY and
   * SARADC reside at global CPU1; CPU2 is not a second CP/AP transport peer. */
  return 1;
#endif
}

static uint8_t bk7258_mbipc_crc8(const uint8_t *data, uint16_t len)
{
  uint8_t crc = 0;
  uint16_t i;
  uint8_t bit;

  for (i = 0; i < len; i++)
    {
      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc & UINT8_C(0x80)) ?
            (uint8_t)((crc << 1) ^ UINT8_C(0x31)) : (uint8_t)(crc << 1);
        }
    }

  return crc;
}

static uint32_t bk7258_mbipc_server_handle(uint8_t port)
{
  return BK7258_MBIPC_SERVER_HANDLE | port;
}

static uint32_t bk7258_mbipc_connection_handle(uint8_t port, uint8_t conn)
{
  return BK7258_MBIPC_CONNECT_HANDLE | port |
         ((uint32_t)conn << BK7258_MBIPC_HANDLE_CONN_SHIFT);
}

static struct bk7258_mbipc_socket_s *
bk7258_mbipc_socket_from_handle(uint32_t handle)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);

  if ((handle & BK7258_MBIPC_CONNECT_HANDLE) != 0)
    {
      uint8_t conn = (uint8_t)((handle & BK7258_MBIPC_HANDLE_CONN_MASK) >>
                               BK7258_MBIPC_HANDLE_CONN_SHIFT);
      if (port >= SERVER_PORT_MIN && port <= SERVER_PORT_MAX &&
          conn < BK7258_MBIPC_CONNECTIONS)
        {
          return &g_mbipc.server[port - SERVER_PORT_MIN].connection[conn];
        }
    }
  else if (port >= CLIENT_PORT_MIN && port <= CLIENT_PORT_MAX)
    {
      return &g_mbipc.client[port - CLIENT_PORT_MIN];
    }

  return NULL;
}

static struct bk7258_mbipc_socket_s *
bk7258_mbipc_receiver(uint8_t dst_port, uint8_t src_cpu, uint8_t src_port,
                       uint8_t connect_id)
{
  unsigned int i;

  if (dst_port >= SERVER_PORT_MIN && dst_port <= SERVER_PORT_MAX)
    {
      if (connect_id >= BK7258_MBIPC_CONNECTIONS)
        {
          return NULL;
        }

      return &g_mbipc.server[dst_port - SERVER_PORT_MIN].connection[connect_id];
    }

  if (dst_port >= CLIENT_PORT_MIN && dst_port <= CLIENT_PORT_MAX)
    {
      struct bk7258_mbipc_socket_s *socket =
        &g_mbipc.client[dst_port - CLIENT_PORT_MIN];
      if ((socket->state & BK7258_MBIPC_STATE_CONNECTED) != 0 &&
          socket->dst_cpu == src_cpu && socket->dst_port == src_port)
        {
          return socket;
        }
    }

  return NULL;
}

static int bk7258_mbipc_send_frame(uint8_t kind, uint8_t command,
                                   struct bk7258_mbipc_socket_s *socket,
                                   uint8_t route_status, uint8_t api_status,
                                   const uint8_t *payload, uint16_t length,
                                   uint16_t offset, uint16_t fragment)
{
  uint8_t frame[sizeof(struct bk7258_mbipc_frame_s) + BK7258_MBIPC_FRAGMENT_BYTES];
  struct bk7258_mbipc_frame_s *header =
    (struct bk7258_mbipc_frame_s *)frame;
  int tx_limit;
  int ret;

  if (!g_mbipc.online || !is_rpmsg_ept_ready(&g_mbipc.ept))
    {
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_UNREACHABLE;
    }

  tx_limit = rpmsg_get_tx_buffer_size(&g_mbipc.ept);
  if (tx_limit < (int)(sizeof(*header) + fragment) ||
      fragment > BK7258_MBIPC_FRAGMENT_BYTES)
    {
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_QUEUE_FULL;
    }

  memset(header, 0, sizeof(*header));
  header->magic = BK7258_MBIPC_MAGIC;
  header->version = BK7258_MBIPC_VERSION;
  header->kind = kind;
  header->command = command;
  header->src_cpu = socket->src_cpu;
  header->dst_cpu = socket->dst_cpu;
  header->src_port = socket->src_port;
  header->dst_port = socket->dst_port;
  header->connect_id = socket->connect_id;
  header->tag = socket->tx_tag;
  header->user_cmd = socket->tx_command;
  header->route_status = route_status;
  header->api_status = api_status;
  header->total_len = length;
  header->fragment_offset = offset;
  header->fragment_len = fragment;
  header->crc8 = payload == NULL ? 0 : bk7258_mbipc_crc8(payload, length);

  if (fragment != 0)
    {
      memcpy(header->payload, payload + offset, fragment);
    }

  ret = rpmsg_send(&g_mbipc.ept, frame, sizeof(*header) + fragment);
  return ret < 0 ? -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_UNREACHABLE : 0;
}

static int bk7258_mbipc_transmit(uint8_t kind, uint8_t command,
                                 struct bk7258_mbipc_socket_s *socket,
                                 uint8_t route_status, uint8_t api_status,
                                 const uint8_t *payload, uint16_t length)
{
  uint16_t offset = 0;
  int ret;

  do
    {
      uint16_t fragment = length - offset;
      if (fragment > BK7258_MBIPC_FRAGMENT_BYTES)
        {
          fragment = BK7258_MBIPC_FRAGMENT_BYTES;
        }

      ret = bk7258_mbipc_send_frame(kind, command, socket, route_status,
                                    api_status, payload, length, offset,
                                    fragment);
      if (ret < 0)
        {
          return ret;
        }

      offset += fragment;
    }
  while (offset < length || (length == 0 && offset++ == 0));

  return 0;
}

static void bk7258_mbipc_complete_tx(struct bk7258_mbipc_socket_s *socket,
                                     uint8_t status)
{
  socket->tx_status = status;
  socket->state &= ~BK7258_MBIPC_STATE_TX;
  nxsem_post(&socket->tx_sem);
}

static void bk7258_mbipc_reset_socket(struct bk7258_mbipc_socket_s *socket)
{
  socket->state = 0;
  socket->dst_cpu = 0;
  socket->dst_port = 0;
  socket->connect_id = BK7258_MBIPC_INVALID_CONNECT;
  socket->rx_total = 0;
  socket->rx_next = 0;
  nxsem_reset(&socket->tx_sem, 0);
}

static void bk7258_mbipc_endpoint_unbind(struct rpmsg_endpoint *ept)
{
  unsigned int i;
  unsigned int j;

  (void)ept;
  nxmutex_lock(&g_mbipc.lock);
  g_mbipc.online = false;
  g_mbipc.rdev = NULL;

  for (i = 0; i < BK7258_MBIPC_CLIENT_PORTS; i++)
    {
      if ((g_mbipc.client[i].state & BK7258_MBIPC_STATE_TX) != 0)
        {
          bk7258_mbipc_complete_tx(&g_mbipc.client[i], MB_IPC_DISCONNECTED);
        }
      g_mbipc.client[i].state &= ~BK7258_MBIPC_STATE_CONNECTED;
    }

  for (i = 0; i < BK7258_MBIPC_SERVER_PORTS; i++)
    {
      for (j = 0; j < BK7258_MBIPC_CONNECTIONS; j++)
        {
          if ((g_mbipc.server[i].connection[j].state &
               BK7258_MBIPC_STATE_TX) != 0)
            {
              bk7258_mbipc_complete_tx(&g_mbipc.server[i].connection[j],
                                       MB_IPC_DISCONNECTED);
            }
          g_mbipc.server[i].connection[j].state &=
            ~BK7258_MBIPC_STATE_CONNECTED;
        }
    }

  nxmutex_unlock(&g_mbipc.lock);
}

static int bk7258_mbipc_receive_request(const struct bk7258_mbipc_frame_s *frame,
                                        size_t frame_len)
{
  struct bk7258_mbipc_socket_s *socket;
  uint16_t payload_len;
  uint8_t event_port;
  uint8_t event_conn;

  if (frame_len < sizeof(*frame) ||
      frame->fragment_len > BK7258_MBIPC_FRAGMENT_BYTES ||
      frame->fragment_offset + frame->fragment_len > frame->total_len ||
      frame->total_len > BK7258_MBIPC_MAX_PAYLOAD ||
      frame_len != sizeof(*frame) + frame->fragment_len)
    {
      return -EINVAL;
    }

  socket = bk7258_mbipc_receiver(frame->dst_port, frame->src_cpu,
                                 frame->src_port, frame->connect_id);
  if (socket == NULL)
    {
      return -ENOENT;
    }

  if (frame->fragment_offset == 0)
    {
      socket->rx_total = frame->total_len;
      socket->rx_next = 0;
      socket->rx_tag = frame->tag;
      socket->rx_command = frame->command;
      socket->rx_user_cmd = frame->user_cmd;
      socket->state |= BK7258_MBIPC_STATE_RX;
    }

  if ((socket->state & BK7258_MBIPC_STATE_RX) == 0 ||
      socket->rx_total != frame->total_len ||
      socket->rx_next != frame->fragment_offset)
    {
      return -EINVAL;
    }

  payload_len = frame->fragment_len;
  if (payload_len != 0)
    {
      memcpy(socket->buffer + socket->rx_next, frame->payload, payload_len);
    }
  socket->rx_next += payload_len;

  if (socket->rx_next == socket->rx_total)
    {
      if (bk7258_mbipc_crc8(socket->buffer, socket->rx_total) != frame->crc8)
        {
          socket->state &= ~BK7258_MBIPC_STATE_RX;
          return -EBADMSG;
        }

      event_port = socket->src_port;
      event_conn = socket->connect_id;
      if (event_port >= SERVER_PORT_MIN && event_port <= SERVER_PORT_MAX &&
          g_mbipc.server[event_port - SERVER_PORT_MIN].callback != NULL)
        {
          g_mbipc.server[event_port - SERVER_PORT_MIN].callback(
            bk7258_mbipc_connection_handle(event_port, event_conn), event_conn);
        }
    }

  return 0;
}

static int bk7258_mbipc_endpoint_cb(struct rpmsg_endpoint *ept, void *data,
                                    size_t len, uint32_t src, void *priv)
{
  struct bk7258_mbipc_frame_s *frame = data;
  struct bk7258_mbipc_socket_s *socket;
  unsigned int i;

  (void)ept;
  (void)src;
  (void)priv;

  if (len < sizeof(*frame) || frame->magic != BK7258_MBIPC_MAGIC ||
      frame->version != BK7258_MBIPC_VERSION)
    {
      return RPMSG_SUCCESS;
    }

  nxmutex_lock(&g_mbipc.lock);
  if (frame->kind == BK7258_MBIPC_FRAME_CONNECT)
    {
      if (frame->dst_port < SERVER_PORT_MIN ||
          frame->dst_port > SERVER_PORT_MAX ||
          !g_mbipc.server[frame->dst_port - SERVER_PORT_MIN].allocated)
        {
          nxmutex_unlock(&g_mbipc.lock);
          return RPMSG_SUCCESS;
        }

      for (i = 0; i < BK7258_MBIPC_CONNECTIONS; i++)
        {
          socket = &g_mbipc.server[frame->dst_port - SERVER_PORT_MIN].connection[i];
          if ((socket->state & BK7258_MBIPC_STATE_CONNECTED) == 0)
            {
              socket->state = BK7258_MBIPC_STATE_ALLOCATED |
                              BK7258_MBIPC_STATE_CONNECTED;
              socket->src_cpu = bk7258_mbipc_local_cpu();
              socket->src_port = frame->dst_port;
              socket->dst_cpu = frame->src_cpu;
              socket->dst_port = frame->src_port;
              socket->connect_id = (uint8_t)i;
              socket->tx_tag = frame->tag;
              (void)bk7258_mbipc_transmit(BK7258_MBIPC_FRAME_ACK,
                                           MB_IPC_CONNECT_CMD | MB_IPC_RSP_FLAG,
                                           socket, IPC_ROUTE_STATUS_OK,
                                           IPC_API_IMPL_STATUS_OK, NULL, 0);
              break;
            }
        }
      nxmutex_unlock(&g_mbipc.lock);
      return RPMSG_SUCCESS;
    }

  socket = bk7258_mbipc_receiver(frame->dst_port, frame->src_cpu,
                                 frame->src_port, frame->connect_id);
  if (socket == NULL)
    {
      nxmutex_unlock(&g_mbipc.lock);
      return RPMSG_SUCCESS;
    }

  if (frame->kind == BK7258_MBIPC_FRAME_ACK)
    {
      if ((socket->state & BK7258_MBIPC_STATE_TX) != 0 &&
          socket->tx_tag == frame->tag)
        {
          if (socket->tx_command == MB_IPC_CONNECT_CMD &&
              frame->command == (MB_IPC_CONNECT_CMD | MB_IPC_RSP_FLAG))
            {
              socket->connect_id = frame->connect_id;
              socket->state |= BK7258_MBIPC_STATE_CONNECTED;
            }
          bk7258_mbipc_complete_tx(socket, MB_IPC_TX_OK);
        }
      nxmutex_unlock(&g_mbipc.lock);
      return RPMSG_SUCCESS;
    }

  if (frame->kind == BK7258_MBIPC_FRAME_DISCONNECT)
    {
      bk7258_mbipc_reset_socket(socket);
      nxmutex_unlock(&g_mbipc.lock);
      return RPMSG_SUCCESS;
    }

  (void)bk7258_mbipc_receive_request(frame, len);
  nxmutex_unlock(&g_mbipc.lock);
  return RPMSG_SUCCESS;
}

static void bk7258_mbipc_device_created(struct rpmsg_device *rdev, void *priv)
{
  (void)priv;

  if (strcmp(rpmsg_get_cpuname(rdev),
#ifdef CONFIG_BK7258_COMPONENT_CP
             "ap"
#else
             "cp"
#endif
             ) != 0)
    {
      return;
    }

  nxmutex_lock(&g_mbipc.lock);
  if (g_mbipc.rdev == NULL)
    {
      g_mbipc.ept.priv = &g_mbipc;
      g_mbipc.ept.ns_bound_cb = NULL;
      g_mbipc.rdev = rdev;
      (void)rpmsg_create_ept(&g_mbipc.ept, rdev, BK7258_MBIPC_SERVICE_NAME,
                             RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
                             bk7258_mbipc_endpoint_cb,
                             bk7258_mbipc_endpoint_unbind);
      g_mbipc.online = is_rpmsg_ept_ready(&g_mbipc.ept);
    }
  nxmutex_unlock(&g_mbipc.lock);
}

static void bk7258_mbipc_device_destroy(struct rpmsg_device *rdev, void *priv)
{
  (void)priv;

  nxmutex_lock(&g_mbipc.lock);
  if (g_mbipc.rdev == rdev)
    {
      rpmsg_destroy_ept(&g_mbipc.ept);
      bk7258_mbipc_endpoint_unbind(&g_mbipc.ept);
    }
  nxmutex_unlock(&g_mbipc.lock);
}

bk_err_t bk7258_mb_ipc_transport_initialize(void)
{
  int ret;

  nxmutex_lock(&g_mbipc.lock);
  if (g_mbipc.registered)
    {
      nxmutex_unlock(&g_mbipc.lock);
      return BK_OK;
    }
  g_mbipc.registered = true;
  nxmutex_unlock(&g_mbipc.lock);

  ret = rpmsg_register_callback(&g_mbipc, bk7258_mbipc_device_created,
                                bk7258_mbipc_device_destroy, NULL, NULL);
  if (ret < 0)
    {
      nxmutex_lock(&g_mbipc.lock);
      g_mbipc.registered = false;
      nxmutex_unlock(&g_mbipc.lock);
      return BK_FAIL;
    }

  return BK_OK;
}

bk_err_t mb_ipc_init(void)
{
  return g_mbipc.registered ? BK_OK : BK_FAIL;
}

u32 mb_ipc_socket(u8 port, void *rx_callback)
{
  unsigned int i;

  nxmutex_lock(&g_mbipc.lock);
  if (port >= SERVER_PORT_MIN && port <= SERVER_PORT_MAX)
    {
      struct bk7258_mbipc_server_s *server =
        &g_mbipc.server[port - SERVER_PORT_MIN];
      server->allocated = true;
      server->callback = (mb_ipc_notify_isr_t)rx_callback;
      for (i = 0; i < BK7258_MBIPC_CONNECTIONS; i++)
        {
          struct bk7258_mbipc_socket_s *socket = &server->connection[i];
          if ((socket->state & BK7258_MBIPC_STATE_ALLOCATED) == 0)
            {
              nxsem_init(&socket->tx_sem, 0, 0);
              socket->connect_id = (uint8_t)i;
              socket->src_cpu = bk7258_mbipc_local_cpu();
              socket->src_port = port;
              socket->state = BK7258_MBIPC_STATE_ALLOCATED;
            }
        }
      nxmutex_unlock(&g_mbipc.lock);
      return bk7258_mbipc_server_handle(port);
    }

  if (port >= CLIENT_PORT_MIN && port <= CLIENT_PORT_MAX)
    {
      struct bk7258_mbipc_socket_s *socket =
        &g_mbipc.client[port - CLIENT_PORT_MIN];
      if ((socket->state & BK7258_MBIPC_STATE_ALLOCATED) == 0)
        {
          memset(socket, 0, sizeof(*socket));
          nxsem_init(&socket->tx_sem, 0, 0);
          socket->connect_id = BK7258_MBIPC_INVALID_CONNECT;
          socket->src_cpu = bk7258_mbipc_local_cpu();
          socket->src_port = port;
          socket->callback = (mb_ipc_notify_isr_t)rx_callback;
          socket->state = BK7258_MBIPC_STATE_ALLOCATED;
        }
      nxmutex_unlock(&g_mbipc.lock);
      return port;
    }

  nxmutex_unlock(&g_mbipc.lock);
  return 0;
}

int mb_ipc_connect(u32 handle, u8 dst_cpu, u8 dst_port, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int ret;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }
  if (dst_port < SERVER_PORT_MIN || dst_port > SERVER_PORT_MAX)
    {
      return -MB_IPC_INVALID_PORT;
    }
  if ((socket->state & BK7258_MBIPC_STATE_ALLOCATED) == 0 ||
      (socket->state & BK7258_MBIPC_STATE_CONNECTED) != 0)
    {
      return -MB_IPC_INVALID_STATE;
    }

  socket->dst_cpu = dst_cpu;
  socket->dst_port = dst_port;
  socket->tx_command = MB_IPC_CONNECT_CMD;
  socket->tx_tag++;
  socket->state |= BK7258_MBIPC_STATE_TX;
  nxsem_reset(&socket->tx_sem, 0);
  ret = bk7258_mbipc_transmit(BK7258_MBIPC_FRAME_CONNECT, MB_IPC_CONNECT_CMD,
                              socket, IPC_ROUTE_STATUS_OK,
                              IPC_API_IMPL_STATUS_OK, NULL, 0);
  if (ret < 0)
    {
      socket->state &= ~BK7258_MBIPC_STATE_TX;
      return ret;
    }

  ret = nxsem_tickwait_uninterruptible(&socket->tx_sem, MSEC2TICK(timeout));
  if (ret < 0)
    {
      socket->state &= ~BK7258_MBIPC_STATE_TX;
      return -MB_IPC_TX_TIMEOUT;
    }

  return socket->tx_status == MB_IPC_TX_OK ? 0 : -socket->tx_status;
}

int mb_ipc_disconnect(u32 handle, u8 dst_cpu, u8 dst_port, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);

  (void)dst_cpu;
  (void)dst_port;
  (void)timeout;
  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  (void)bk7258_mbipc_transmit(BK7258_MBIPC_FRAME_DISCONNECT,
                              MB_IPC_DISCONNECT_CMD, socket,
                              IPC_ROUTE_STATUS_OK, IPC_API_IMPL_STATUS_OK,
                              NULL, 0);
  bk7258_mbipc_reset_socket(socket);
  return 0;
}

int mb_ipc_close(u32 handle, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  (void)timeout;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  bk7258_mbipc_reset_socket(socket);
  return 0;
}

int mb_ipc_send(u32 handle, u8 user_cmd, u8 *data, u32 data_len, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int ret;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }
  if ((socket->state & BK7258_MBIPC_STATE_CONNECTED) == 0)
    {
      return -MB_IPC_INVALID_STATE;
    }
  if ((socket->state & BK7258_MBIPC_STATE_TX) != 0)
    {
      return -MB_IPC_TX_BUSY;
    }
  if (data_len > BK7258_MBIPC_MAX_PAYLOAD || (data_len != 0 && data == NULL))
    {
      return -MB_IPC_INVALID_PARAM;
    }

  socket->tx_command = MB_IPC_SEND_CMD;
  socket->tx_tag++;
  socket->state |= BK7258_MBIPC_STATE_TX;
  nxsem_reset(&socket->tx_sem, 0);
  ret = bk7258_mbipc_transmit(BK7258_MBIPC_FRAME_REQUEST, MB_IPC_SEND_CMD,
                              socket, IPC_ROUTE_STATUS_OK,
                              IPC_API_IMPL_STATUS_OK, data, (uint16_t)data_len);
  if (ret < 0)
    {
      socket->state &= ~BK7258_MBIPC_STATE_TX;
      return ret;
    }

  ret = nxsem_tickwait_uninterruptible(&socket->tx_sem, MSEC2TICK(timeout));
  if (ret < 0)
    {
      socket->state &= ~BK7258_MBIPC_STATE_TX;
      return -MB_IPC_TX_TIMEOUT;
    }

  return socket->tx_status == MB_IPC_TX_OK ? 0 : -socket->tx_status;
}

int mb_ipc_get_recv_data_len(u32 handle)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  if (socket == NULL || (socket->state & BK7258_MBIPC_STATE_RX) == 0)
    {
      return -MB_IPC_NO_DATA;
    }

  return socket->rx_total;
}

int mb_ipc_get_recv_event(u32 handle, u32 *event)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  if (socket == NULL || event == NULL ||
      (socket->state & BK7258_MBIPC_STATE_RX) == 0)
    {
      return -MB_IPC_NO_DATA;
    }

  *event = socket->rx_command;
  return 0;
}

int mb_ipc_recv(u32 handle, u8 *user_cmd, u8 *data, u32 length, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int ret;

  (void)timeout;
  if (socket == NULL || (socket->state & BK7258_MBIPC_STATE_RX) == 0)
    {
      return -MB_IPC_NO_DATA;
    }

  if (user_cmd != NULL)
    {
      *user_cmd = socket->rx_user_cmd;
    }

  if (data != NULL && length != 0)
    {
      if (length < socket->rx_total)
        {
          return -MB_IPC_INVALID_PARAM;
        }
      memcpy(data, socket->buffer, socket->rx_total);
    }

  socket->tx_command = socket->rx_command;
  socket->tx_tag = socket->rx_tag;
  ret = bk7258_mbipc_transmit(BK7258_MBIPC_FRAME_ACK,
                              socket->rx_command | MB_IPC_RSP_FLAG, socket,
                              IPC_ROUTE_STATUS_OK, IPC_API_IMPL_STATUS_OK,
                              NULL, 0);
  socket->state &= ~BK7258_MBIPC_STATE_RX;
  return ret < 0 ? ret : (data == NULL || length == 0 ? 0 : socket->rx_total);
}

u32 mb_ipc_server_get_connect_handle(u32 handle, u32 connect_id)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);
  if ((handle & BK7258_MBIPC_SERVER_HANDLE) == 0 ||
      port < SERVER_PORT_MIN || port > SERVER_PORT_MAX ||
      connect_id >= BK7258_MBIPC_CONNECTIONS)
    {
      return 0;
    }

  return bk7258_mbipc_connection_handle(port, (uint8_t)connect_id);
}

int mb_ipc_server_close(u32 handle, u32 timeout)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);
  unsigned int i;

  (void)timeout;
  if ((handle & BK7258_MBIPC_SERVER_HANDLE) == 0 ||
      port < SERVER_PORT_MIN || port > SERVER_PORT_MAX)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  g_mbipc.server[port - SERVER_PORT_MIN].allocated = false;
  for (i = 0; i < BK7258_MBIPC_CONNECTIONS; i++)
    {
      bk7258_mbipc_reset_socket(
        &g_mbipc.server[port - SERVER_PORT_MIN].connection[i]);
    }

  return 0;
}

int mb_ipc_get_connection(u32 handle, u8 *src, u8 *dst)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  if (socket == NULL || src == NULL || dst == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  *src = socket->dst_cpu;
  *dst = socket->src_cpu;
  return 0;
}

