const source=`/****************************************************************************
 * chips/bk7258/mb_ipc/mb_ipc_rpmsg.c
 *
 * NuttX/RPMsg transport adaptation for the imported Armino mb_ipc ABI.
 *
 * The authority mb_ipc state machine is preserved: server/client ports,
 * connection slots, tags, request consumption, CRC-8, command replies,
 * timeout, and disconnect status retain their public meaning. Only the
 * mailbox command's shared-memory payload pointer is replaced with framed,
 * bounded RPMsg payload fragments because a pointer from CPU0 is not a valid
 * payload descriptor for the AP endpoint.
 ****************************************************************************/

#include <nuttx/config.h>

#if defined(CONFIG_RPMSG) && defined(CONFIG_BK7258_MBIPC)

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/rpmsg/rpmsg.h>
#include <nuttx/semaphore.h>

#include <openamp/rpmsg.h>

#include <common/bk_include.h>
#include <driver/mb_ipc.h>
#include <driver/mb_ipc_port_cfg.h>

#include <bk7258_mb_ipc.h>

#define BK7258_MBIPC_SERVICE             "bk7258.mb_ipc.v1"
#define BK7258_MBIPC_MAGIC               UINT32_C(0x4d424950) /* MBIP */
#define BK7258_MBIPC_VERSION             UINT8_C(1)
#define BK7258_MBIPC_FRAGMENT_BYTES      384
#define BK7258_MBIPC_MAX_PAYLOAD         1024
#define BK7258_MBIPC_SERVER_PORTS        4
#define BK7258_MBIPC_CLIENT_PORTS        12
#define BK7258_MBIPC_CONNECTIONS         3
#define BK7258_MBIPC_INVALID_CONNECTION  UINT8_C(0xff)

#define BK7258_MBIPC_FRAME_COMMAND       UINT8_C(0)
#define BK7258_MBIPC_FRAME_RESPONSE      UINT8_C(1)
#define BK7258_MBIPC_FRAME_CONNECT       UINT8_C(2)
#define BK7258_MBIPC_FRAME_DISCONNECT    UINT8_C(3)

#define BK7258_MBIPC_ALLOCATED            UINT8_C(0x01)
#define BK7258_MBIPC_CONNECTED            UINT8_C(0x02)
#define BK7258_MBIPC_TX_PENDING           UINT8_C(0x04)
#define BK7258_MBIPC_RX_REASSEMBLING      UINT8_C(0x08)
#define BK7258_MBIPC_RX_READY             UINT8_C(0x10)

#define BK7258_MBIPC_SERVER_HANDLE        UINT32_C(0x80000000)
#define BK7258_MBIPC_CONNECTION_HANDLE    UINT32_C(0x40000000)
#define BK7258_MBIPC_HANDLE_PORT_MASK     UINT32_C(0x0000003f)
#define BK7258_MBIPC_HANDLE_CONN_SHIFT    8
#define BK7258_MBIPC_HANDLE_CONN_MASK     UINT32_C(0x00000300)

typedef u32 (*bk7258_mbipc_notify_t)(u32 handle, u32 connection);

begin_packed_struct struct bk7258_mbipc_frame_s
{
  uint32_t magic;
  uint16_t generation;
  uint16_t total_len;
  uint16_t fragment_offset;
  uint16_t fragment_len;
  uint8_t version;
  uint8_t kind;
  uint8_t command;
  uint8_t src_cpu;
  uint8_t dst_cpu;
  uint8_t src_port;
  uint8_t dst_port;
  uint8_t connection;
  uint8_t tag;
  uint8_t user_cmd;
  uint8_t route_status;
  uint8_t api_status;
  uint8_t crc8;
  uint8_t payload[0];
} end_packed_struct;

struct bk7258_mbipc_transaction_s
{
  uint16_t generation;
  uint16_t total_len;
  uint16_t next_offset;
  uint16_t read_offset;
  uint8_t cpu;
  uint8_t port;
  uint8_t connection;
  uint8_t tag;
  uint8_t command;
  uint8_t user_cmd;
  uint8_t crc8;
};

struct bk7258_mbipc_socket_s
{
  uint8_t state;
  uint8_t local_cpu;
  uint8_t local_port;
  uint8_t peer_cpu;
  uint8_t peer_port;
  uint8_t connection;
  uint8_t next_tag;
  uint16_t next_generation;
  int tx_result;
  struct bk7258_mbipc_transaction_s tx;
  struct bk7258_mbipc_transaction_s rx;
  bk7258_mbipc_notify_t notify;
  sem_t tx_sem;
  sem_t rx_sem;
  uint8_t payload[BK7258_MBIPC_MAX_PAYLOAD];
};

struct bk7258_mbipc_server_s
{
  bool allocated;
  bk7258_mbipc_notify_t notify;
  struct bk7258_mbipc_socket_s slot[BK7258_MBIPC_CONNECTIONS];
};

struct bk7258_mbipc_s
{
  nxmutex_t state_lock;
  nxmutex_t send_lock;
  struct rpmsg_endpoint endpoint;
  struct rpmsg_device *rdev;
  bool registered;
  bool endpoint_created;
  bool endpoint_bound;
  struct bk7258_mbipc_server_s server[BK7258_MBIPC_SERVER_PORTS];
  struct bk7258_mbipc_socket_s client[BK7258_MBIPC_CLIENT_PORTS];
};

static struct bk7258_mbipc_s g_mbipc =
{
  .state_lock = NXMUTEX_INITIALIZER,
  .send_lock = NXMUTEX_INITIALIZER,
};

static uint8_t bk7258_mbipc_local_cpu(void)
{
#ifdef CONFIG_BK7258_COMPONENT_CP
  return 0;
#else
  /* CPU1 and CPU2 form one AP SMP image. The authority PHY/SARADC clients
   * are global CPU1 clients, so CPU2 never becomes a CP/AP mb_ipc peer. */
  return 1;
#endif
}

static uint8_t bk7258_mbipc_crc8(const uint8_t *data, uint16_t length)
{
  uint8_t crc = 0;
  uint16_t index;
  uint8_t bit;

  for (index = 0; index < length; index++)
    {
      crc ^= data[index];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc & UINT8_C(0x80)) ?
            (uint8_t)((crc << 1) ^ UINT8_C(0x31)) : (uint8_t)(crc << 1);
        }
    }

  return crc;
}

static uint32_t bk7258_mbipc_server_handle(uint8_t port)
{
  return BK7258_MBIPC_SERVER_HANDLE | port;
}

static uint32_t bk7258_mbipc_connection_handle(uint8_t port, uint8_t slot)
{
  return BK7258_MBIPC_CONNECTION_HANDLE | port |
         ((uint32_t)slot << BK7258_MBIPC_HANDLE_CONN_SHIFT);
}

static void bk7258_mbipc_socket_init(struct bk7258_mbipc_socket_s *socket,
                                     uint8_t local_cpu, uint8_t local_port,
                                     uint8_t connection)
{
  memset(socket, 0, sizeof(*socket));
  socket->state = BK7258_MBIPC_ALLOCATED;
  socket->local_cpu = local_cpu;
  socket->local_port = local_port;
  socket->connection = connection;
  socket->next_generation = 1;
  nxsem_init(&socket->tx_sem, 0, 0);
  nxsem_init(&socket->rx_sem, 0, 0);
}

static void bk7258_mbipc_disconnect_locked(struct bk7258_mbipc_socket_s *socket,
                                           int result)
{
  if ((socket->state & BK7258_MBIPC_TX_PENDING) != 0)
    {
      socket->tx_result = result;
      socket->state &= ~BK7258_MBIPC_TX_PENDING;
      nxsem_post(&socket->tx_sem);
    }

  socket->state &= ~(BK7258_MBIPC_CONNECTED |
                     BK7258_MBIPC_RX_REASSEMBLING |
                     BK7258_MBIPC_RX_READY);
  socket->peer_cpu = 0;
  socket->peer_port = 0;
  socket->connection = BK7258_MBIPC_INVALID_CONNECTION;
  socket->rx.total_len = 0;
  socket->rx.next_offset = 0;
  socket->rx.read_offset = 0;
  nxsem_reset(&socket->rx_sem, 0);
}

static struct bk7258_mbipc_socket_s *
bk7258_mbipc_socket_from_handle(uint32_t handle)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);

  if ((handle & BK7258_MBIPC_CONNECTION_HANDLE) != 0)
    {
      uint8_t slot = (uint8_t)((handle & BK7258_MBIPC_HANDLE_CONN_MASK) >>
                               BK7258_MBIPC_HANDLE_CONN_SHIFT);
      if (port >= SERVER_PORT_MIN && port <= SERVER_PORT_MAX &&
          slot < BK7258_MBIPC_CONNECTIONS)
        {
          return &g_mbipc.server[port - SERVER_PORT_MIN].slot[slot];
        }
    }
  else if (port >= CLIENT_PORT_MIN && port <= CLIENT_PORT_MAX)
    {
      return &g_mbipc.client[port - CLIENT_PORT_MIN];
    }

  return NULL;
}

static struct bk7258_mbipc_socket_s *
bk7258_mbipc_lookup_receiver(uint8_t local_port, uint8_t peer_cpu,
                              uint8_t peer_port, uint8_t connection)
{
  struct bk7258_mbipc_socket_s *socket;

  if (local_port >= SERVER_PORT_MIN && local_port <= SERVER_PORT_MAX)
    {
      if (connection >= BK7258_MBIPC_CONNECTIONS)
        {
          return NULL;
        }

      socket = &g_mbipc.server[local_port - SERVER_PORT_MIN].slot[connection];
      if ((socket->state & BK7258_MBIPC_CONNECTED) == 0 ||
          socket->peer_cpu != peer_cpu || socket->peer_port != peer_port)
        {
          return NULL;
        }

      return socket;
    }

  if (local_port >= CLIENT_PORT_MIN && local_port <= CLIENT_PORT_MAX)
    {
      socket = &g_mbipc.client[local_port - CLIENT_PORT_MIN];
      if ((socket->state & BK7258_MBIPC_CONNECTED) == 0 ||
          socket->peer_cpu != peer_cpu || socket->peer_port != peer_port ||
          socket->connection != connection)
        {
          return NULL;
        }

      return socket;
    }

  return NULL;
}

static int bk7258_mbipc_send_raw(uint8_t kind, uint8_t command,
                                 uint8_t src_cpu, uint8_t src_port,
                                 uint8_t dst_cpu, uint8_t dst_port,
                                 uint8_t connection, uint8_t tag,
                                 uint16_t generation, uint8_t user_cmd,
                                 uint8_t route_status, uint8_t api_status,
                                 const uint8_t *payload, uint16_t total_len,
                                 uint16_t offset, uint16_t fragment_len,
                                 uint8_t crc8)
{
  uint8_t frame[sizeof(struct bk7258_mbipc_frame_s) + BK7258_MBIPC_FRAGMENT_BYTES];
  struct bk7258_mbipc_frame_s *header =
    (struct bk7258_mbipc_frame_s *)frame;
  int limit;
  int result;

  if (!g_mbipc.endpoint_bound || !is_rpmsg_ept_ready(&g_mbipc.endpoint))
    {
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_UNREACHABLE;
    }

  limit = rpmsg_get_tx_buffer_size(&g_mbipc.endpoint);
  if (fragment_len > BK7258_MBIPC_FRAGMENT_BYTES ||
      limit < (int)(sizeof(*header) + fragment_len))
    {
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_QUEUE_FULL;
    }

  memset(header, 0, sizeof(*header));
  header->magic = BK7258_MBIPC_MAGIC;
  header->generation = generation;
  header->total_len = total_len;
  header->fragment_offset = offset;
  header->fragment_len = fragment_len;
  header->version = BK7258_MBIPC_VERSION;
  header->kind = kind;
  header->command = command;
  header->src_cpu = src_cpu;
  header->dst_cpu = dst_cpu;
  header->src_port = src_port;
  header->dst_port = dst_port;
  header->connection = connection;
  header->tag = tag;
  header->user_cmd = user_cmd;
  header->route_status = route_status;
  header->api_status = api_status;
  header->crc8 = crc8;
  if (fragment_len != 0)
    {
      memcpy(header->payload, payload + offset, fragment_len);
    }

  nxmutex_lock(&g_mbipc.send_lock);
  result = rpmsg_trysend(&g_mbipc.endpoint, frame,
                         sizeof(*header) + fragment_len);
  nxmutex_unlock(&g_mbipc.send_lock);
  return result < 0 ? -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_QUEUE_FULL : 0;
}

static int bk7258_mbipc_send_transaction(uint8_t kind,
                                         struct bk7258_mbipc_socket_s *socket,
                                         const struct bk7258_mbipc_transaction_s *txn,
                                         uint8_t route_status,
                                         uint8_t api_status,
                                         const uint8_t *payload)
{
  uint16_t offset = 0;
  uint8_t crc8 = payload == NULL ? 0 :
                 bk7258_mbipc_crc8(payload, txn->total_len);
  int result;

  do
    {
      uint16_t fragment = txn->total_len - offset;
      if (fragment > BK7258_MBIPC_FRAGMENT_BYTES)
        {
          fragment = BK7258_MBIPC_FRAGMENT_BYTES;
        }

      result = bk7258_mbipc_send_raw(kind, txn->command,
                                     socket->local_cpu, socket->local_port,
                                     socket->peer_cpu, socket->peer_port,
                                     socket->connection, txn->tag,
                                     txn->generation, txn->user_cmd,
                                     route_status, api_status, payload,
                                     txn->total_len, offset, fragment, crc8);
      if (result < 0)
        {
          return result;
        }

      offset += fragment;
    }
  while (offset < txn->total_len ||
         (txn->total_len == 0 && offset++ == 0));

  return 0;
}

static int bk7258_mbipc_send_response(
  struct bk7258_mbipc_socket_s *socket,
  const struct bk7258_mbipc_transaction_s *request,
  uint8_t route_status, uint8_t api_status)
{
  return bk7258_mbipc_send_raw(BK7258_MBIPC_FRAME_RESPONSE,
                                request->command | MB_IPC_RSP_FLAG,
                                socket->local_cpu, socket->local_port,
                                request->cpu, request->port,
                                request->connection, request->tag,
                                request->generation, request->user_cmd,
                                route_status, api_status, NULL, 0, 0, 0, 0);
}

static void bk7258_mbipc_complete_tx_locked(
  struct bk7258_mbipc_socket_s *socket, int result)
{
  socket->tx_result = result;
  socket->state &= ~BK7258_MBIPC_TX_PENDING;
  nxsem_post(&socket->tx_sem);
}

static bool bk7258_mbipc_frame_valid(const struct bk7258_mbipc_frame_s *frame,
                                     size_t length)
{
  return length >= sizeof(*frame) &&
         frame->magic == BK7258_MBIPC_MAGIC &&
         frame->version == BK7258_MBIPC_VERSION &&
         frame->fragment_len <= BK7258_MBIPC_FRAGMENT_BYTES &&
         frame->total_len <= BK7258_MBIPC_MAX_PAYLOAD &&
         frame->fragment_offset + frame->fragment_len <= frame->total_len &&
         length == sizeof(*frame) + frame->fragment_len;
}

static int bk7258_mbipc_accept_connect(
  const struct bk7258_mbipc_frame_s *frame)
{
  struct bk7258_mbipc_server_s *server;
  struct bk7258_mbipc_socket_s *socket = NULL;
  unsigned int slot;
  int result;

  if (frame->dst_cpu != bk7258_mbipc_local_cpu() ||
      frame->dst_port < SERVER_PORT_MIN || frame->dst_port > SERVER_PORT_MAX)
    {
      return -MB_IPC_INVALID_PORT;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  server = &g_mbipc.server[frame->dst_port - SERVER_PORT_MIN];
  if (!server->allocated)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_NOT_INITED;
    }

  for (slot = 0; slot < BK7258_MBIPC_CONNECTIONS; slot++)
    {
      struct bk7258_mbipc_socket_s *candidate = &server->slot[slot];
      if ((candidate->state & BK7258_MBIPC_CONNECTED) != 0 &&
          candidate->peer_cpu == frame->src_cpu &&
          candidate->peer_port == frame->src_port)
        {
          socket = candidate;
          break;
        }
      if (socket == NULL && (candidate->state & BK7258_MBIPC_CONNECTED) == 0)
        {
          socket = candidate;
        }
    }

  if (socket == NULL)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_RX_BUSY;
    }

  socket->peer_cpu = frame->src_cpu;
  socket->peer_port = frame->src_port;
  socket->connection = (uint8_t)(socket - server->slot);
  socket->state |= BK7258_MBIPC_CONNECTED;
  nxmutex_unlock(&g_mbipc.state_lock);

  result = bk7258_mbipc_send_raw(BK7258_MBIPC_FRAME_RESPONSE,
                                 MB_IPC_CONNECT_CMD | MB_IPC_RSP_FLAG,
                                 socket->local_cpu, socket->local_port,
                                 socket->peer_cpu, socket->peer_port,
                                 socket->connection, frame->tag,
                                 frame->generation, INVALID_USER_CMD_ID,
                                 IPC_ROUTE_STATUS_OK, IPC_API_IMPL_STATUS_OK,
                                 NULL, 0, 0, 0, 0);
  return result;
}

static int bk7258_mbipc_begin_receive(
  struct bk7258_mbipc_socket_s *socket,
  const struct bk7258_mbipc_frame_s *frame)
{
  if ((socket->state & (BK7258_MBIPC_RX_REASSEMBLING |
                        BK7258_MBIPC_RX_READY)) != 0)
    {
      if (socket->rx.generation == frame->generation &&
          socket->rx.tag == frame->tag &&
          socket->rx.command == frame->command &&
          socket->rx.cpu == frame->src_cpu && socket->rx.port == frame->src_port)
        {
          return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_RX_BUSY;
        }

      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_RX_BUSY;
    }

  socket->rx.generation = frame->generation;
  socket->rx.total_len = frame->total_len;
  socket->rx.next_offset = 0;
  socket->rx.read_offset = 0;
  socket->rx.cpu = frame->src_cpu;
  socket->rx.port = frame->src_port;
  socket->rx.connection = frame->connection;
  socket->rx.tag = frame->tag;
  socket->rx.command = frame->command;
  socket->rx.user_cmd = frame->user_cmd;
  socket->rx.crc8 = frame->crc8;
  socket->state |= BK7258_MBIPC_RX_REASSEMBLING;
  return 0;
}

static int bk7258_mbipc_receive_command(
  const struct bk7258_mbipc_frame_s *frame,
  bk7258_mbipc_notify_t *notify, uint32_t *handle, uint32_t *slot)
{
  struct bk7258_mbipc_socket_s *socket;
  int result;

  *notify = NULL;
  *handle = 0;
  *slot = 0;

  nxmutex_lock(&g_mbipc.state_lock);
  socket = bk7258_mbipc_lookup_receiver(frame->dst_port, frame->src_cpu,
                                         frame->src_port, frame->connection);
  if (socket == NULL)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_INVALID_STATE;
    }

  if (frame->fragment_offset == 0)
    {
      result = bk7258_mbipc_begin_receive(socket, frame);
      if (result < 0)
        {
          nxmutex_unlock(&g_mbipc.state_lock);
          return result;
        }
    }

  if ((socket->state & BK7258_MBIPC_RX_REASSEMBLING) == 0 ||
      socket->rx.generation != frame->generation ||
      socket->rx.next_offset != frame->fragment_offset ||
      socket->rx.total_len != frame->total_len ||
      socket->rx.tag != frame->tag || socket->rx.command != frame->command ||
      socket->rx.cpu != frame->src_cpu || socket->rx.port != frame->src_port)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_RX_BUSY;
    }

  if (frame->fragment_len != 0)
    {
      memcpy(socket->payload + socket->rx.next_offset, frame->payload,
             frame->fragment_len);
    }
  socket->rx.next_offset += frame->fragment_len;

  if (socket->rx.next_offset == socket->rx.total_len)
    {
      if (bk7258_mbipc_crc8(socket->payload, socket->rx.total_len) !=
          socket->rx.crc8)
        {
          socket->state &= ~BK7258_MBIPC_RX_REASSEMBLING;
          nxmutex_unlock(&g_mbipc.state_lock);
          return -MB_IPC_API_BASE_FAILED - IPC_API_IMPL_RX_DATA_FAILED;
        }

      socket->state &= ~BK7258_MBIPC_RX_REASSEMBLING;
      socket->state |= BK7258_MBIPC_RX_READY;
      nxsem_post(&socket->rx_sem);
      if (socket->local_port >= SERVER_PORT_MIN &&
          socket->local_port <= SERVER_PORT_MAX)
        {
          *notify = g_mbipc.server[socket->local_port - SERVER_PORT_MIN].notify;
          *handle = bk7258_mbipc_connection_handle(socket->local_port,
                                                    socket->connection);
          *slot = socket->connection;
        }
      else
        {
          *notify = socket->notify;
          *handle = socket->local_port;
        }
    }

  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

static int bk7258_mbipc_handle_response(
  const struct bk7258_mbipc_frame_s *frame)
{
  struct bk7258_mbipc_socket_s *socket;
  int result = MB_IPC_TX_OK;

  nxmutex_lock(&g_mbipc.state_lock);
  socket = bk7258_mbipc_lookup_receiver(frame->dst_port, frame->src_cpu,
                                         frame->src_port, frame->connection);
  if (socket == NULL || (socket->state & BK7258_MBIPC_TX_PENDING) == 0 ||
      socket->tx.generation != frame->generation ||
      socket->tx.tag != frame->tag ||
      frame->command != (uint8_t)(socket->tx.command | MB_IPC_RSP_FLAG))
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_ROUTE_BASE_FAILED - IPC_ROUTE_UNMATCHED_RSP;
    }

  if (frame->route_status != IPC_ROUTE_STATUS_OK)
    {
      result = MB_IPC_ROUTE_BASE_FAILED + frame->route_status;
    }
  else if (frame->api_status != IPC_API_IMPL_STATUS_OK)
    {
      result = MB_IPC_API_BASE_FAILED + frame->api_status;
    }

  if (socket->tx.command == MB_IPC_CONNECT_CMD && result == MB_IPC_TX_OK)
    {
      socket->connection = frame->connection;
      socket->state |= BK7258_MBIPC_CONNECTED;
    }

  if (socket->tx.command == MB_IPC_DISCONNECT_CMD)
    {
      socket->state &= ~BK7258_MBIPC_CONNECTED;
    }

  bk7258_mbipc_complete_tx_locked(socket, result);
  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

static int bk7258_mbipc_endpoint_cb(struct rpmsg_endpoint *endpoint,
                                    void *data, size_t length,
                                    uint32_t src, void *priv)
{
  const struct bk7258_mbipc_frame_s *frame = data;
  bk7258_mbipc_notify_t notify;
  uint32_t handle;
  uint32_t slot;
  int result;

  (void)endpoint;
  (void)src;
  (void)priv;

  if (!bk7258_mbipc_frame_valid(frame, length) ||
      frame->dst_cpu != bk7258_mbipc_local_cpu())
    {
      return RPMSG_SUCCESS;
    }

  if (frame->kind == BK7258_MBIPC_FRAME_CONNECT)
    {
      result = bk7258_mbipc_accept_connect(frame);
      if (result < 0)
        {
          (void)bk7258_mbipc_send_raw(BK7258_MBIPC_FRAME_RESPONSE,
                                      MB_IPC_CONNECT_CMD | MB_IPC_RSP_FLAG,
                                      bk7258_mbipc_local_cpu(), frame->dst_port,
                                      frame->src_cpu, frame->src_port,
                                      frame->connection, frame->tag,
                                      frame->generation, INVALID_USER_CMD_ID,
                                      IPC_ROUTE_UNREACHABLE,
                                      IPC_API_IMPL_NOT_INITED,
                                      NULL, 0, 0, 0, 0);
        }
      return RPMSG_SUCCESS;
    }

  if (frame->kind == BK7258_MBIPC_FRAME_RESPONSE)
    {
      (void)bk7258_mbipc_handle_response(frame);
      return RPMSG_SUCCESS;
    }

  if (frame->kind == BK7258_MBIPC_FRAME_DISCONNECT)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      struct bk7258_mbipc_socket_s *socket =
        bk7258_mbipc_lookup_receiver(frame->dst_port, frame->src_cpu,
                                     frame->src_port, frame->connection);
      if (socket != NULL)
        {
          struct bk7258_mbipc_transaction_s transaction =
          {
            .generation = frame->generation,
            .cpu = frame->src_cpu,
            .port = frame->src_port,
            .connection = frame->connection,
            .tag = frame->tag,
            .command = MB_IPC_DISCONNECT_CMD,
            .user_cmd = INVALID_USER_CMD_ID,
          };
          nxmutex_unlock(&g_mbipc.state_lock);
          (void)bk7258_mbipc_send_response(socket, &transaction,
                                            IPC_ROUTE_STATUS_OK,
                                            IPC_API_IMPL_STATUS_OK);
          nxmutex_lock(&g_mbipc.state_lock);
          bk7258_mbipc_disconnect_locked(socket, MB_IPC_DISCONNECTED);
        }
      nxmutex_unlock(&g_mbipc.state_lock);
      return RPMSG_SUCCESS;
    }

  result = bk7258_mbipc_receive_command(frame, &notify, &handle, &slot);
  if (result < 0)
    {
      (void)bk7258_mbipc_send_raw(BK7258_MBIPC_FRAME_RESPONSE,
                                  frame->command | MB_IPC_RSP_FLAG,
                                  bk7258_mbipc_local_cpu(), frame->dst_port,
                                  frame->src_cpu, frame->src_port,
                                  frame->connection, frame->tag,
                                  frame->generation, frame->user_cmd,
                                  result <= -MB_IPC_ROUTE_BASE_FAILED ?
                                    (uint8_t)(-result - MB_IPC_ROUTE_BASE_FAILED) :
                                    IPC_ROUTE_UNREACHABLE,
                                  result <= -MB_IPC_API_BASE_FAILED ?
                                    (uint8_t)(-result - MB_IPC_API_BASE_FAILED) :
                                    IPC_API_IMPL_RX_DATA_FAILED,
                                  NULL, 0, 0, 0, 0);
      return RPMSG_SUCCESS;
    }

  /* Never invoke application code while holding the transport state mutex. */
  if (notify != NULL)
    {
      notify(handle, slot);
    }

  return RPMSG_SUCCESS;
}

static void bk7258_mbipc_endpoint_bound(struct rpmsg_endpoint *endpoint)
{
  nxmutex_lock(&g_mbipc.state_lock);
  if (endpoint == &g_mbipc.endpoint)
    {
      g_mbipc.endpoint_bound = true;
    }
  nxmutex_unlock(&g_mbipc.state_lock);
}

static void bk7258_mbipc_endpoint_unbind(struct rpmsg_endpoint *endpoint)
{
  unsigned int port;
  unsigned int slot;

  nxmutex_lock(&g_mbipc.state_lock);
  if (endpoint == &g_mbipc.endpoint)
    {
      g_mbipc.endpoint_bound = false;
      for (port = 0; port < BK7258_MBIPC_CLIENT_PORTS; port++)
        {
          bk7258_mbipc_disconnect_locked(&g_mbipc.client[port],
                                         MB_IPC_DISCONNECTED);
        }
      for (port = 0; port < BK7258_MBIPC_SERVER_PORTS; port++)
        {
          for (slot = 0; slot < BK7258_MBIPC_CONNECTIONS; slot++)
            {
              bk7258_mbipc_disconnect_locked(&g_mbipc.server[port].slot[slot],
                                             MB_IPC_DISCONNECTED);
            }
        }
    }
  nxmutex_unlock(&g_mbipc.state_lock);
}

static void bk7258_mbipc_device_created(struct rpmsg_device *rdev, void *priv)
{
  int result;

  (void)priv;
  if (strcmp(rpmsg_get_cpuname(rdev),
#ifdef CONFIG_BK7258_COMPONENT_CP
             "ap"
#else
             "cp"
#endif
             ) != 0)
    {
      return;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if (g_mbipc.rdev != NULL)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return;
    }
  g_mbipc.rdev = rdev;
  g_mbipc.endpoint.priv = &g_mbipc;
  g_mbipc.endpoint.ns_bound_cb = bk7258_mbipc_endpoint_bound;
  nxmutex_unlock(&g_mbipc.state_lock);

  result = rpmsg_create_ept(&g_mbipc.endpoint, rdev, BK7258_MBIPC_SERVICE,
                            RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
                            bk7258_mbipc_endpoint_cb,
                            bk7258_mbipc_endpoint_unbind);
  if (result < 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      if (g_mbipc.rdev == rdev)
        {
          g_mbipc.rdev = NULL;
        }
      nxmutex_unlock(&g_mbipc.state_lock);
    }
}

static void bk7258_mbipc_device_destroy(struct rpmsg_device *rdev, void *priv)
{
  bool destroy = false;

  (void)priv;
  nxmutex_lock(&g_mbipc.state_lock);
  if (g_mbipc.rdev == rdev)
    {
      g_mbipc.rdev = NULL;
      destroy = g_mbipc.endpoint_created;
      g_mbipc.endpoint_created = false;
    }
  nxmutex_unlock(&g_mbipc.state_lock);

  if (destroy)
    {
      rpmsg_destroy_ept(&g_mbipc.endpoint);
    }
  bk7258_mbipc_endpoint_unbind(&g_mbipc.endpoint);
}

bk_err_t bk7258_mb_ipc_transport_initialize(void)
{
  int result;

  nxmutex_lock(&g_mbipc.state_lock);
  if (g_mbipc.registered)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return BK_OK;
    }
  g_mbipc.registered = true;
  nxmutex_unlock(&g_mbipc.state_lock);

  result = rpmsg_register_callback(&g_mbipc, bk7258_mbipc_device_created,
                                   bk7258_mbipc_device_destroy, NULL, NULL);
  if (result < 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      g_mbipc.registered = false;
      nxmutex_unlock(&g_mbipc.state_lock);
      return BK_FAIL;
    }

  return BK_OK;
}

bk_err_t mb_ipc_init(void)
{
  return g_mbipc.registered ? BK_OK : BK_FAIL;
}

u32 mb_ipc_socket(u8 port, void *rx_callback)
{
  unsigned int slot;

  nxmutex_lock(&g_mbipc.state_lock);
  if (port >= SERVER_PORT_MIN && port <= SERVER_PORT_MAX)
    {
      struct bk7258_mbipc_server_s *server =
        &g_mbipc.server[port - SERVER_PORT_MIN];
      server->allocated = true;
      server->notify = (bk7258_mbipc_notify_t)rx_callback;
      for (slot = 0; slot < BK7258_MBIPC_CONNECTIONS; slot++)
        {
          if ((server->slot[slot].state & BK7258_MBIPC_ALLOCATED) == 0)
            {
              bk7258_mbipc_socket_init(&server->slot[slot],
                                       bk7258_mbipc_local_cpu(), port,
                                       (uint8_t)slot);
            }
        }
      nxmutex_unlock(&g_mbipc.state_lock);
      return bk7258_mbipc_server_handle(port);
    }

  if (port >= CLIENT_PORT_MIN && port <= CLIENT_PORT_MAX)
    {
      struct bk7258_mbipc_socket_s *socket =
        &g_mbipc.client[port - CLIENT_PORT_MIN];
      if ((socket->state & BK7258_MBIPC_ALLOCATED) == 0)
        {
          bk7258_mbipc_socket_init(socket, bk7258_mbipc_local_cpu(), port,
                                   BK7258_MBIPC_INVALID_CONNECTION);
          socket->notify = (bk7258_mbipc_notify_t)rx_callback;
        }
      nxmutex_unlock(&g_mbipc.state_lock);
      return port;
    }

  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

static int bk7258_mbipc_wait_tx(struct bk7258_mbipc_socket_s *socket,
                                 uint32_t timeout)
{
  int result = nxsem_tickwait_uninterruptible(&socket->tx_sem,
                                              MSEC2TICK(timeout));
  if (result < 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      socket->tx.generation++;
      socket->state &= ~BK7258_MBIPC_TX_PENDING;
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_TX_TIMEOUT;
    }

  return socket->tx_result == MB_IPC_TX_OK ? 0 : -socket->tx_result;
}

int mb_ipc_connect(u32 handle, u8 dst_cpu, u8 dst_port, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int result;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }
  if (dst_port < SERVER_PORT_MIN || dst_port > SERVER_PORT_MAX)
    {
      return -MB_IPC_INVALID_PORT;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_ALLOCATED) == 0 ||
      (socket->state & BK7258_MBIPC_CONNECTED) != 0 ||
      (socket->state & BK7258_MBIPC_TX_PENDING) != 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_INVALID_STATE;
    }
  socket->peer_cpu = dst_cpu;
  socket->peer_port = dst_port;
  socket->tx.generation = socket->next_generation++;
  socket->tx.tag = socket->next_tag++;
  socket->tx.command = MB_IPC_CONNECT_CMD;
  socket->tx.user_cmd = INVALID_USER_CMD_ID;
  socket->tx.total_len = 0;
  socket->state |= BK7258_MBIPC_TX_PENDING;
  nxsem_reset(&socket->tx_sem, 0);
  nxmutex_unlock(&g_mbipc.state_lock);

  result = bk7258_mbipc_send_transaction(BK7258_MBIPC_FRAME_CONNECT, socket,
                                          &socket->tx, IPC_ROUTE_STATUS_OK,
                                          IPC_API_IMPL_STATUS_OK, NULL);
  if (result < 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      socket->state &= ~BK7258_MBIPC_TX_PENDING;
      socket->peer_cpu = 0;
      socket->peer_port = 0;
      nxmutex_unlock(&g_mbipc.state_lock);
      return result;
    }

  return bk7258_mbipc_wait_tx(socket, timeout);
}

int mb_ipc_send(u32 handle, u8 user_cmd, u8 *data, u32 length, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int result;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }
  if (length > BK7258_MBIPC_MAX_PAYLOAD || (length != 0 && data == NULL))
    {
      return -MB_IPC_INVALID_PARAM;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_CONNECTED) == 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_INVALID_STATE;
    }
  if ((socket->state & BK7258_MBIPC_TX_PENDING) != 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_TX_BUSY;
    }
  socket->tx.generation = socket->next_generation++;
  socket->tx.tag = socket->next_tag++;
  socket->tx.command = MB_IPC_SEND_CMD;
  socket->tx.user_cmd = user_cmd;
  socket->tx.total_len = (uint16_t)length;
  socket->state |= BK7258_MBIPC_TX_PENDING;
  nxsem_reset(&socket->tx_sem, 0);
  nxmutex_unlock(&g_mbipc.state_lock);

  result = bk7258_mbipc_send_transaction(BK7258_MBIPC_FRAME_COMMAND, socket,
                                          &socket->tx, IPC_ROUTE_STATUS_OK,
                                          IPC_API_IMPL_STATUS_OK, data);
  if (result < 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      socket->state &= ~BK7258_MBIPC_TX_PENDING;
      nxmutex_unlock(&g_mbipc.state_lock);
      return result;
    }

  return bk7258_mbipc_wait_tx(socket, timeout);
}

int mb_ipc_get_recv_data_len(u32 handle)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int result;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  result = (socket->state & BK7258_MBIPC_RX_READY) != 0 ?
           socket->rx.total_len : -MB_IPC_NO_DATA;
  nxmutex_unlock(&g_mbipc.state_lock);
  return result;
}

int mb_ipc_get_recv_event(u32 handle, u32 *event)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);

  if (socket == NULL || event == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_RX_READY) == 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_NO_DATA;
    }
  *event = socket->rx.command & MB_IPC_CMD_MASK;
  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

int mb_ipc_recv(u32 handle, u8 *user_cmd, u8 *data, u32 length,
                u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  struct bk7258_mbipc_transaction_s transaction;
  uint16_t copied = 0;
  bool completed = false;
  int result;

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_RX_READY) == 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      result = nxsem_tickwait_uninterruptible(&socket->rx_sem,
                                              MSEC2TICK(timeout));
      if (result < 0)
        {
          return -MB_IPC_TX_TIMEOUT;
        }
      nxmutex_lock(&g_mbipc.state_lock);
    }

  if ((socket->state & BK7258_MBIPC_RX_READY) == 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_NO_DATA;
    }

  if (user_cmd != NULL)
    {
      *user_cmd = socket->rx.user_cmd;
    }

  if (data == NULL || length == 0)
    {
      socket->rx.read_offset = socket->rx.total_len;
    }
  else
    {
      copied = socket->rx.total_len - socket->rx.read_offset;
      if (copied > length)
        {
          copied = (uint16_t)length;
        }
      memcpy(data, socket->payload + socket->rx.read_offset, copied);
      socket->rx.read_offset += copied;
    }

  if (socket->rx.read_offset == socket->rx.total_len)
    {
      transaction = socket->rx;
      socket->state &= ~BK7258_MBIPC_RX_READY;
      completed = true;
    }
  nxmutex_unlock(&g_mbipc.state_lock);

  if (!completed)
    {
      return copied;
    }

  result = bk7258_mbipc_send_response(socket, &transaction,
                                      IPC_ROUTE_STATUS_OK,
                                      IPC_API_IMPL_STATUS_OK);
  return result < 0 ? result : (data == NULL || length == 0 ? 0 : copied);
}

int mb_ipc_disconnect(u32 handle, u8 dst_cpu, u8 dst_port, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);
  int result;

  (void)dst_cpu;
  (void)dst_port;
  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_CONNECTED) == 0 ||
      (socket->state & BK7258_MBIPC_TX_PENDING) != 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_INVALID_STATE;
    }
  socket->tx.generation = socket->next_generation++;
  socket->tx.tag = socket->next_tag++;
  socket->tx.command = MB_IPC_DISCONNECT_CMD;
  socket->tx.user_cmd = INVALID_USER_CMD_ID;
  socket->tx.total_len = 0;
  socket->state |= BK7258_MBIPC_TX_PENDING;
  nxsem_reset(&socket->tx_sem, 0);
  nxmutex_unlock(&g_mbipc.state_lock);

  result = bk7258_mbipc_send_transaction(BK7258_MBIPC_FRAME_DISCONNECT,
                                          socket, &socket->tx,
                                          IPC_ROUTE_STATUS_OK,
                                          IPC_API_IMPL_STATUS_OK, NULL);
  if (result < 0)
    {
      return result;
    }

  result = bk7258_mbipc_wait_tx(socket, timeout);
  if (result == 0)
    {
      nxmutex_lock(&g_mbipc.state_lock);
      bk7258_mbipc_disconnect_locked(socket, MB_IPC_DISCONNECTED);
      nxmutex_unlock(&g_mbipc.state_lock);
    }
  return result;
}

int mb_ipc_close(u32 handle, u32 timeout)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);

  if (socket == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }
  if ((socket->state & BK7258_MBIPC_CONNECTED) != 0)
    {
      return mb_ipc_disconnect(handle, socket->peer_cpu, socket->peer_port,
                               timeout);
    }

  nxmutex_lock(&g_mbipc.state_lock);
  bk7258_mbipc_disconnect_locked(socket, MB_IPC_DISCONNECTED);
  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

u32 mb_ipc_server_get_connect_handle(u32 handle, u32 connection)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);

  if ((handle & BK7258_MBIPC_SERVER_HANDLE) == 0 ||
      port < SERVER_PORT_MIN || port > SERVER_PORT_MAX ||
      connection >= BK7258_MBIPC_CONNECTIONS)
    {
      return 0;
    }

  return bk7258_mbipc_connection_handle(port, (uint8_t)connection);
}

int mb_ipc_server_close(u32 handle, u32 timeout)
{
  uint8_t port = (uint8_t)(handle & BK7258_MBIPC_HANDLE_PORT_MASK);
  unsigned int slot;

  (void)timeout;
  if ((handle & BK7258_MBIPC_SERVER_HANDLE) == 0 ||
      port < SERVER_PORT_MIN || port > SERVER_PORT_MAX)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  g_mbipc.server[port - SERVER_PORT_MIN].allocated = false;
  for (slot = 0; slot < BK7258_MBIPC_CONNECTIONS; slot++)
    {
      bk7258_mbipc_disconnect_locked(
        &g_mbipc.server[port - SERVER_PORT_MIN].slot[slot],
        MB_IPC_DISCONNECTED);
    }
  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

int mb_ipc_get_connection(u32 handle, u8 *src, u8 *dst)
{
  struct bk7258_mbipc_socket_s *socket =
    bk7258_mbipc_socket_from_handle(handle);

  if (socket == NULL || src == NULL || dst == NULL)
    {
      return -MB_IPC_INVALID_HANDLE;
    }

  nxmutex_lock(&g_mbipc.state_lock);
  if ((socket->state & BK7258_MBIPC_CONNECTED) == 0)
    {
      nxmutex_unlock(&g_mbipc.state_lock);
      return -MB_IPC_INVALID_STATE;
    }
  *src = (uint8_t)((socket->peer_cpu << 6) | socket->peer_port);
  *dst = (uint8_t)((socket->local_cpu << 6) | socket->local_port);
  nxmutex_unlock(&g_mbipc.state_lock);
  return 0;
}

